export const checkInUserToEvent = async (eventId: string, userId: string): Promise<boolean> => {
  try {
    const { error } = await supabase
      .from('event_attendees_new')
      .insert({ 
        event_id: eventId,
        user_id: userId
      });
      
    if (error) throw error;
    
    // Increment the events_attended counter in the user's profile
    const { error: incrementError } = await supabase.rpc('increment_events_attended', { user_id_param: userId });
    if (incrementError) throw incrementError;
    
    return true;
  } catch (error) {
    console.error('Error checking in user to event:', error);
    return false;
  }
};

