// User events-related functions
export const getUserAttendedEvents = async (userId: string): Promise<any[]> => {
  try {
    const { data, error } = await supabase
      .from('event_attendees_new')
      .select('*, events:event_id(*)')
      .eq('user_id', userId);
      
    if (error) throw error;
    
    // Transform the data to return the events instead of the attendee records
    const events = data?.map(record => record.events) || [];
    return events;
  } catch (error) {
    console.error('Error getting user attended events:', error);
    return [];
  }
};

