// Notifications-related functions
export const createEventReminderNotifications = async (eventId: string, message: string): Promise<boolean> => {
  try {
    const { data: interestedUsers, error: interestedError } = await supabase
      .from('event_interested')
      .select('user_id')
      .eq('event_id', eventId);
      
    if (interestedError) throw interestedError;
    
    if (interestedUsers && interestedUsers.length > 0) {
      const notifications = interestedUsers.map((user) => ({
        user_id: user.user_id,
        title: 'Event Reminder',
        message: message,
        type: 'event_reminder',
        related_id: eventId,
        read: false
      }));
      
      const { error: notificationError } = await supabase
        .from('notifications')
        .insert(notifications);
        
      if (notificationError) throw notificationError;
    }
    
    return true;
  } catch (error) {
    console.error('Error creating event reminder notifications:', error);
    return false;
  }
};

